// LIST MODE: Group outputs by row_id, merge batches within each row, output N items
const allOutputs = $input.all();

// Retrieve by index because LLM chain strips input fields from output
let buildOutputItems = [];
try {
  buildOutputItems = $('Build Output Schema').all();
} catch (e) {}

let matchColumn, textColumn, matchSameRow;
try {
  matchColumn = $('String Input').first().json.match_column || 'email';
  textColumn = $('String Input').first().json.text_column || 'Text_to_interpret';
  matchSameRow = $('String Input').first().json.match_same_row !== false;
} catch (e) {
  matchColumn = 'email';
  textColumn = 'Text_to_interpret';
  matchSameRow = true;
}

// Group by row_id; index fallback handles pinned data (no Build Output Schema)
const rowGroups = {};
for (let i = 0; i < allOutputs.length; i++) {
  const item = allOutputs[i];
  const originalItem = buildOutputItems[i]?.json || {};
  const rowKey = originalItem.row_key || originalItem.row_id || `row_${i}`;

  if (!rowGroups[rowKey]) {
    rowGroups[rowKey] = { items: [], matchValue: originalItem.row_id, bodyCore: originalItem.body_core };
  }
  rowGroups[rowKey].items.push(item);
}

const results = [];
for (const group of Object.values(rowGroups)) {
  const items = group.items;
  const matchValue = group.matchValue;
  const merged = {};
  let confidenceData = null;
  const errors = [];

  for (const item of items) {
    const output = item.json.output;
    // A failed batch (onError: continue) arrives as { error }. Report it; never fill the gap with a guess
    if (!output) errors.push(item.json.error || 'LLM returned no output for this batch of columns');
    if (output) {
      if (output.confidence) {
        confidenceData = output.confidence;
        delete output.confidence;
      }
      Object.assign(merged, output);
    }
  }

  delete merged._row_id;

  // Written only if the sheet has an extraction_error column; empty on success clears an old error
  merged.extraction_error = errors.join(' | ').slice(0, 500);

  if (confidenceData) {
    merged.confidence_score = confidenceData.overall || 0;
    merged.confidence_low_fields = Array.isArray(confidenceData.low_confidence_fields) 
      ? confidenceData.low_confidence_fields.join(', ') : '';
    merged.confidence_reasoning = confidenceData.reasoning || '';
    merged.review_needed = (confidenceData.overall || 0) < 70;
  }

  // FIX: Write Extracted Row is hardcoded to match on 'email' column, so we must always populate it
  if (matchValue) {
    merged[matchColumn] = matchValue;
    if (matchColumn !== 'email') {
      merged.email = matchValue;
    }
  }

  // FIX: Only set textColumn if different from matchColumn to prevent overwriting match value
  if (group.bodyCore && textColumn !== matchColumn) {
    merged[textColumn] = group.bodyCore;
  }

  // Dedupe extracted emails into email + more_emails fields
  if (Array.isArray(merged.extracted_emails)) {
    const baseEmails = matchValue ? [matchValue] : [];
    const allEmails = [...new Set([...baseEmails, ...merged.extracted_emails].filter(Boolean))];
    merged.email = allEmails[0];
    merged.more_emails = allEmails.slice(1).join(', ');
  }

  // Remove observability fields (not written to sheet)
  delete merged.confidence_score;
  delete merged.confidence_low_fields;
  delete merged.confidence_reasoning;
  delete merged.review_needed;

  // Write Extracted Row always matches on `email`. Without that field it appends a new row;
  // an empty string would instead match, and overwrite, the first row whose email is blank
  if (!matchSameRow || !merged.email) delete merged.email;

  results.push({ json: merged });
}

return results;

// Outputs N_rows × M_batches items; each carries schema batch + row context for LLM
const inputRows = $('String Input').all();
const textColumn = $('String Input').first().json.text_column;
const matchColumn = $('String Input').first().json.match_column || 'email';
const batchSize = $('String Input').first().json.batch_size;
const extractDepth = $('String Input').first().json.extract_depth;
const schemaSheetName = $('String Input').first().json.schema_sheet_name || 'Description_hig7f6';

// CRM field-to-depth mapping (fields not listed default to depth 3)
const DEPTH_MAP = {
  'first_name': 1, 'surname': 1, 'email': 1,
  'last_topic': 1, 'last_being_contacted': 1, 'last_contacted': 1,
  'more_emails': 2, 'status': 2, 'association': 2, 'groups': 2,
  'goal_contact_frequency': 2, 'current_job': 2, 'works_at': 2
};

// Try to get schema from multiple sources
let schemaRows = [];

// Source 1: If schema was just created via LLM, use that output
try {
  const llmOutput = $('Generate Schema with LLM').first().json.output;
  if (Array.isArray(llmOutput) && llmOutput.length > 0) {
    schemaRows = llmOutput;
  }
} catch (e) {}

// Source 2: If schema exists in sheet, parse from fetched data
if (schemaRows.length === 0) {
  const sheetData = $('Try Fetch Schema Sheet').all();
  if (sheetData.length > 0 && sheetData[0].json.ColumnName) {
    schemaRows = sheetData.map(item => item.json);
  }
}

const schemaItems = schemaRows.map(row => ({ json: row }));

// Exclude text_column - no point extracting input back into output
const filteredSchema = schemaItems.filter(item => item.json.ColumnName !== textColumn);

// Filter fields by depth (depth 3 = all fields, no filtering)
const fieldsToExtract = extractDepth >= 3
  ? filteredSchema
  : filteredSchema.filter(item => (DEPTH_MAP[item.json.ColumnName] || 3) <= extractDepth);

// Convert our simple types (str/int/list/class) to JSON Schema
function buildSchemaFromBatch(batch) {
  const properties = {};
  const requiredFields = [];

  for (const item of batch) {
    const columnName = item.json.ColumnName;
    const columnType = item.json.Type;
    const columnDescr = item.json.Description;

    if (columnName && columnType) {
      if (columnType === 'class') {
        const classValues = item.json.Classes
          ? item.json.Classes.split(',').map(s => s.trim()).filter(Boolean)
          : [];
        if (classValues.length === 0) {
          throw new Error(
            `Schema error in schema sheet (${schemaSheetName}): column "${columnName}" has Type "class" but the "Classes" column is empty. ` +
            `Fix: add comma-separated values to the "Classes" column for "${columnName}".`
          );
        }
        properties[columnName] = {
          type: "string",
          description: columnDescr,
          enum: classValues
        };
      } else {
        let jsonType = columnType;
        if (columnType === 'str') jsonType = 'string';
        else if (columnType === 'list') jsonType = 'array';
        else if (columnType === 'date') jsonType = 'string';
        else if (columnType === 'int') jsonType = 'integer';

        properties[columnName] = {
          type: jsonType,
          description: columnDescr
        };

        if (jsonType === 'array') {
          properties[columnName].items = { type: "string" };
        }
        // Note: no format:'date' — LLM may return empty strings for missing dates
      }
      requiredFields.push(columnName);
    }
  }

  // LLM self-reports extraction confidence for observability
  properties.confidence = {
    type: "object",
    description: "Confidence scores for extraction quality",
    properties: {
      overall: { type: "integer", minimum: 0, maximum: 100, description: "Weighted average confidence (0-100)" },
      low_confidence_fields: { type: "array", items: { type: "string" }, description: "Fields with confidence < 70" },
      reasoning: { type: "string", description: "Brief explanation of uncertainty" }
    },
    required: ["overall"]
  };
  requiredFields.push("confidence");

  return { type: "object", properties, required: requiredFields };
}

// Reserve 3 slots for confidence sub-properties (overall, low_confidence_fields, reasoning)
const effectiveBatchSize = Math.max(1, batchSize - 3);

// Build batches from depth-filtered fields
const results = [];
for (const [rowIndex, row] of inputRows.entries()) {
  const rowId = row.json[matchColumn] || row.json.match_value || row.json.email;
  const bodyCore = row.json.body_core || '';
  // Nothing to read: skip, rather than ask the LLM to invent values for an empty text
  if (!String(bodyCore).trim()) continue;

  const batches = [];
  for (let i = 0; i < fieldsToExtract.length; i += effectiveBatchSize) {
    batches.push(fieldsToExtract.slice(i, i + effectiveBatchSize));
  }

  for (const batch of batches) {
    const schema = buildSchemaFromBatch(batch);
    results.push({
      json: {
        schema: schema,
        body_core: bodyCore,
        row_id: rowId,
        // Groups the batches of one row in Merge Outputs, even when the row has no match value
        row_key: rowId || `row_${rowIndex}`,
        match_column: matchColumn,
        contact_name: row.json.contact_name,
        contact_email: row.json.contact_email,
        subject: row.json.subject
      }
    });
  }
}

return results;
